<template>
	<NcModal
		:name="dialogTitle"
		size="normal"
		@close="$emit('close')">
		<div class="dialog">
			<h2 class="dialog__title">
				{{ dialogTitle }}
			</h2>

			<NcNoteCard v-if="hrMode" type="info">
				{{ t('absence', 'Record an absence on behalf of an employee (e.g. sick leave). It is booked directly, without an approval step.') }}
			</NcNoteCard>

			<div v-if="hrMode" class="dialog__field">
				<label class="dialog__label">{{ t('absence', 'Employee') }}</label>
				<!-- eslint-disable @nextcloud/no-deprecated-library-props -- NcSelectUsers migration deferred: needs live-instance testing -->
				<NcSelect
					v-model="selectedEmployee"
					:options="employeeOptions"
					:loading="employeeLoading"
					:userSelect="true"
					label="displayName"
					:filterable="false"
					:placeholder="t('absence', 'Search for an employee…')"
					:aria-label-combobox="t('absence', 'Employee')"
					@search="onEmployeeSearch" />
				<!-- eslint-enable @nextcloud/no-deprecated-library-props -->
			</div>

			<div class="dialog__field">
				<label class="dialog__label">{{ t('absence', 'Leave type') }}</label>
				<NcSelect
					v-model="selectedType"
					:options="typeOptions"
					label="label"
					:clearable="false"
					:aria-label-combobox="t('absence', 'Leave type')">
					<template #option="{ icon, label }">
						<span class="opt"><span class="opt__icon">{{ icon }}</span>{{ label }}</span>
					</template>
					<template #selected-option="{ icon, label }">
						<span class="opt"><span class="opt__icon">{{ icon }}</span>{{ label }}</span>
					</template>
				</NcSelect>
			</div>

			<div v-if="showSickCategories" class="dialog__field">
				<label class="dialog__label">{{ t('absence', 'Category') }}</label>
				<NcSelect
					v-model="sickCategory"
					:options="sickCategoryOptions"
					label="label"
					:clearable="false"
					:aria-label-combobox="t('absence', 'Category')">
					<template #option="{ icon, label }">
						<span class="opt"><span class="opt__icon">{{ icon }}</span>{{ label }}</span>
					</template>
					<template #selected-option="{ icon, label }">
						<span class="opt"><span class="opt__icon">{{ icon }}</span>{{ label }}</span>
					</template>
				</NcSelect>
				<p class="dialog__hint">
					{{ t('absence', 'Only HR ever sees this category — everyone else, including the employee, sees a neutral absence.') }}
				</p>
			</div>

			<div v-if="showDisability" class="dialog__field">
				<NcCheckboxRadioSwitch v-model="disability">
					{{ t('absence', 'Disability-related leave') }}
				</NcCheckboxRadioSwitch>
				<p class="dialog__hint">
					{{ t('absence', 'For the additional statutory entitlement. Only HR can set and see this flag.') }}
				</p>
			</div>

			<div v-if="needsReplacement" class="dialog__field">
				<label class="dialog__label">
					{{ t('absence', 'Replacement') }}<span v-if="replacementRequired" class="dialog__req">*</span>
					<span v-else class="dialog__optional">{{ t('absence', '(optional)') }}</span>
				</label>
				<!-- eslint-disable @nextcloud/no-deprecated-library-props -- NcSelectUsers migration deferred: needs live-instance testing -->
				<NcSelect
					v-model="selectedReplacement"
					:options="replacementOptions"
					:loading="replacementLoading"
					:userSelect="true"
					label="displayName"
					:filterable="false"
					:placeholder="replacementPlaceholder"
					:aria-label-combobox="t('absence', 'Replacement')"
					@search="onReplacementSearch" />
				<!-- eslint-enable @nextcloud/no-deprecated-library-props -->
				<p class="dialog__hint">
					{{ replacementHint }}
				</p>
			</div>

			<div class="dialog__row">
				<div class="dialog__field">
					<label class="dialog__label">{{ t('absence', 'From') }}</label>
					<NcDateTimePickerNative v-model="startDate" type="date" />
				</div>
				<div class="dialog__field">
					<label class="dialog__label">{{ t('absence', 'To') }}</label>
					<NcDateTimePickerNative v-model="endDate" type="date" />
				</div>
			</div>

			<div class="dialog__field">
				<label class="dialog__label">
					{{ t('absence', 'Working days') }}<span class="dialog__req">*</span>
				</label>
				<NcTextField
					:modelValue="workingDays"
					type="number"
					min="0"
					step="0.5"
					:label="t('absence', 'Working days')"
					:labelVisible="false"
					@update:modelValue="onWorkingDaysInput" />
				<p class="dialog__hint dialog__hint--estimate">
					<span aria-hidden="true">⚠️</span>
					<template v-if="prefillActive">
						{{ t('absence', 'Prefilled from your') }}
						<a
							:href="settingsUrl"
							target="_blank"
							rel="noreferrer noopener"
							class="dialog__link">{{ t('absence', 'working days and public holidays') }}</a>
						{{ t('absence', '— this is only an estimate: always check the number and adjust it manually if it is off.') }}
						<template v-if="!hrMode">
							{{ t('absence', 'Your manager will verify it.') }}
						</template>
					</template>
					<template v-else>
						{{ t('absence', 'Number of working days this absence covers (excluding weekends and public holidays) — this is only an estimate: always check the number and adjust it manually if it is off.') }}
						<template v-if="!hrMode">
							{{ t('absence', 'Your manager will verify it.') }}
						</template>
					</template>
				</p>
			</div>

			<div v-if="balanceRow && !hrMode && workingDaysNum > 0" class="preview" :style="{ '--type-color': typeColor }">
				<div class="preview__balance">
					<span>{{ t('absence', 'Available') }}</span>
					<strong>{{ formatDays(balanceRow.available) }} → {{ formatDays(projectedAvailable) }}</strong>
					<span class="preview__bar" role="presentation">
						<span class="preview__bar-fill" :style="{ width: availablePct + '%' }" />
					</span>
				</div>
			</div>

			<NcNoteCard v-if="wouldGoNegative" type="warning">
				{{ t('absence', 'Heads up: this goes beyond your available balance. You can still submit — HR may approve it.') }}
			</NcNoteCard>

			<NcNoteCard v-if="overlapCount" :type="coverageTight ? 'warning' : 'info'">
				<template v-if="coverageTight">
					{{ n('absence', 'Heads up: %n colleague is already off then ({names}), so approving this would leave the team thin. You can still submit.', 'Heads up: %n colleagues are already off then ({names}), so approving this would leave the team thin. You can still submit.', overlapCount, { names: overlapLabel }) }}
				</template>
				<template v-else>
					{{ n('absence', '%n colleague is off then ({names}).', '%n colleagues are off then ({names}).', overlapCount, { names: overlapLabel }) }}
				</template>
			</NcNoteCard>

			<div class="dialog__field">
				<label class="dialog__label">
					{{ t('absence', 'Reason') }}
					<span v-if="requiresNote" class="dialog__req">*</span>
					<span v-else class="dialog__optional">{{ t('absence', '(optional)') }}</span>
				</label>
				<NcTextArea
					v-model="reason"
					:placeholder="t('absence', 'Optional note for your manager')"
					resize="vertical"
					rows="2" />
			</div>

			<div class="dialog__actions">
				<NcButton variant="tertiary" @click="$emit('close')">
					{{ t('absence', 'Cancel') }}
				</NcButton>
				<NcButton variant="primary" :disabled="!canSubmit || submitting" @click="submit">
					<template #icon>
						<NcLoadingIcon v-if="submitting" :size="20" />
						<Send v-else :size="20" />
					</template>
					{{ submitLabel }}
				</NcButton>
			</div>
		</div>
	</NcModal>
</template>

<script>
import { showError } from '@nextcloud/dialogs'
import { n, t } from '@nextcloud/l10n'
import { generateUrl } from '@nextcloud/router'
import NcButton from '@nextcloud/vue/components/NcButton'
import NcCheckboxRadioSwitch from '@nextcloud/vue/components/NcCheckboxRadioSwitch'
import NcDateTimePickerNative from '@nextcloud/vue/components/NcDateTimePickerNative'
import NcLoadingIcon from '@nextcloud/vue/components/NcLoadingIcon'
import NcModal from '@nextcloud/vue/components/NcModal'
import NcNoteCard from '@nextcloud/vue/components/NcNoteCard'
import NcSelect from '@nextcloud/vue/components/NcSelect'
import NcTextArea from '@nextcloud/vue/components/NcTextArea'
import NcTextField from '@nextcloud/vue/components/NcTextField'
import Send from 'vue-material-design-icons/Send.vue'
import api from '../api.js'
import { store } from '../store.js'
import { countWorkingDays, parseWeekdays, toIso } from '../utils/dates.js'
import { formatRegionCode, makeHolidayChecker } from '../utils/holidays.js'

export default {
	name: 'RequestDialog',
	components: { NcCheckboxRadioSwitch, NcModal, NcSelect, NcDateTimePickerNative, NcTextArea, NcTextField, NcNoteCard, NcButton, NcLoadingIcon, Send },

	props: {
		request: { type: Object, default: null },
		// HR "record absence for an employee" mode (e.g. sick leave).
		hrMode: { type: Boolean, default: false },
	},

	emits: ['close', 'saved'],
	data() {
		return {
			selectedType: null,
			sickCategory: null,
			disability: false,
			startIso: null,
			endIso: null,
			workingDays: '',
			// True once the user edits the field by hand — stops auto-prefill from
			// overwriting their number (§7: prefilled but manually changeable).
			workingDaysTouched: false,
			holidayChecker: null,
			reason: '',
			submitting: false,
			selectedEmployee: null,
			employeeOptions: [],
			employeeLoading: false,
			selectedReplacement: null,
			replacementOptions: [],
			replacementLoading: false,
			// Who else on the team is off during the picked dates (§8), fetched as the
			// dates change. `coverageSeq` discards answers overtaken by a newer range.
			coverage: null,
			coverageSeq: 0,
			coverageTimer: null,
		}
	},

	computed: {
		isEdit() {
			return this.request !== null
		},

		dialogTitle() {
			if (this.hrMode) {
				return t('absence', 'Record absence')
			}
			return this.isEdit ? t('absence', 'Edit request') : t('absence', 'Request time off')
		},

		submitLabel() {
			if (this.isEdit) {
				return t('absence', 'Save changes')
			}
			// HR records directly — there is no request/approval flow.
			return this.hrMode ? t('absence', 'Record') : t('absence', 'Submit request')
		},

		typeOptions() {
			// HR may record any enabled type (incl. sick); employees only self-requestable ones.
			// HR correcting an existing record needs the same full list — otherwise the
			// record's own type (sick) is missing from the picker it is preselected in.
			if (this.hrMode || (this.isEdit && store.session.isHr)) {
				// Confidential categories (hrOnly) are picked as a sub-option of sick
				// leave, not as top-level types — unless no sick type exists to hang
				// them off, in which case they stay listed directly.
				return store.enabledLeaveTypes.filter((t) => !t.hrOnly || !this.sickType)
			}
			return store.requestableLeaveTypes
		},

		/** The type keyed 'sick' that the confidential categories nest under. */
		sickType() {
			return store.enabledLeaveTypes.find((t) => t.key === 'sick' && t.enabled) || null
		},

		/** Confidential (HR-only) types — the server only sends these to HR. */
		confidentialCategories() {
			return store.enabledLeaveTypes.filter((t) => t.hrOnly)
		},

		showSickCategories() {
			return (this.hrMode || (this.isEdit && store.session.isHr))
				&& this.confidentialCategories.length > 0
				&& this.selectedType
				&& this.sickType
				&& this.selectedType.id === this.sickType.id
		},

		/**
		 * The disability flag (§5.8) is HR's alone, and belongs to annual leave —
		 * the additional statutory entitlement it marks is annual leave.
		 */
		showDisability() {
			return (this.hrMode || (this.isEdit && store.session.isHr))
				&& this.selectedType
				&& this.selectedType.key === 'annual'
		},

		sickCategoryOptions() {
			return [
				{ id: null, icon: this.sickType ? this.sickType.icon : '🤒', label: t('absence', 'General sick leave') },
				...this.confidentialCategories.map((c) => ({ id: c.id, icon: c.icon, label: c.label })),
			]
		},

		typeColor() {
			return this.selectedType ? this.selectedType.color : 'var(--color-primary-element)'
		},

		requiresNote() {
			return this.selectedType ? this.selectedType.requiresNote : false
		},

		needsReplacement() {
			return this.selectedType ? this.selectedType.requiresReplacement : false
		},

		/** Whether this dialog is about the signed-in user's own leave. */
		isOwnLeave() {
			return this.subjectUid === store.session.uid
		},

		/**
		 * Whose absence this is, for wording aimed at somebody else's record.
		 * Empty until HR has picked an employee, which the strings below allow for.
		 */
		subjectName() {
			if (this.hrMode) {
				return this.selectedEmployee ? this.selectedEmployee.displayName : ''
			}
			return this.request ? (this.request.employeeName || this.request.employeeUid) : ''
		},

		/**
		 * Demanded only of somebody arranging their own leave: they know who can cover
		 * and are asked to sort it out before going (§5.1). HR recording an absence for
		 * somebody else is stating a fact, often after it happened, and cannot nominate
		 * cover on their behalf — so the field is offered there but never required.
		 * Mirrors the same rule in RequestService::resolveReplacement().
		 */
		replacementRequired() {
			return this.needsReplacement && this.isOwnLeave
		},

		replacementPlaceholder() {
			return this.isOwnLeave
				? t('absence', 'Who covers for you?')
				: t('absence', 'Who is the replacement?')
		},

		replacementHint() {
			if (this.isOwnLeave) {
				return t('absence', 'A colleague who covers your duties while you are away. They are notified once your leave is approved.')
			}
			return this.subjectName
				? t('absence', 'Optional. A colleague who covers for {name} while they are away, and is notified once this is recorded.', { name: this.subjectName })
				: t('absence', 'Optional. A colleague who covers these duties while this employee is away, and is notified once this is recorded.')
		},

		// Bridge the native date pickers (Date objects) to our ISO string state.
		startDate: {
			get() {
				return this.startIso ? new Date(this.startIso + 'T00:00:00') : null
			},

			set(v) {
				this.startIso = v ? toIso(v) : null
				// Keep the end on/after the start.
				if (this.startIso && this.endIso && this.endIso < this.startIso) {
					this.endIso = this.startIso
				}
			},
		},

		endDate: {
			get() {
				return this.endIso ? new Date(this.endIso + 'T00:00:00') : null
			},

			set(v) {
				this.endIso = v ? toIso(v) : null
			},
		},

		subjectUid() {
			// Whose leave this is — that person can't be their own replacement.
			return this.hrMode ? (this.selectedEmployee && this.selectedEmployee.uid) : (this.request ? this.request.employeeUid : store.session.uid)
		},

		workingDaysNum() {
			const v = parseFloat(this.workingDays)
			return Number.isFinite(v) ? v : 0
		},

		// The prefill note (with a link to the settings) only shows while the value
		// is still auto-filled; once edited or when editing, use the plain text.
		prefillActive() {
			return !this.isEdit && !this.workingDaysTouched
		},

		settingsUrl() {
			return generateUrl('/settings/user/availability')
		},

		balanceRow() {
			// The store holds the current user's balance, so only meaningful for
			// self-service. Match the year the leave starts in — the balance list is
			// sorted newest-year first, so taking the first type match would show
			// next year's numbers as soon as any next-year data exists. When there is
			// no row for that year yet (e.g. booking far ahead), show no preview
			// rather than a wrong one.
			if (!this.selectedType || this.hrMode || !this.startIso) {
				return null
			}
			const year = parseInt(this.startIso.slice(0, 4), 10)
			return store.balance.balances.find((b) => b.typeId === this.selectedType.id && b.year === year && b.entitlement !== null) || null
		},

		projectedAvailable() {
			if (!this.balanceRow) {
				return null
			}
			return Math.round((this.balanceRow.available - this.workingDaysNum) * 10) / 10
		},

		wouldGoNegative() {
			return this.balanceRow && this.selectedType && this.selectedType.countsAgainstBalance && this.projectedAvailable < 0
		},

		availablePct() {
			if (!this.balanceRow || !this.balanceRow.entitlement) {
				return 0
			}
			return Math.max(0, Math.min(100, (this.projectedAvailable / this.balanceRow.entitlement) * 100))
		},

		/**
		 * The coverage endpoint answers for *my* team, so the warning only means
		 * something when the leave is my own. HR recording an absence for someone
		 * else would otherwise be shown their own colleagues, which is worse than
		 * showing nothing.
		 */
		coverageApplies() {
			return !this.hrMode && this.subjectUid === store.session.uid
		},

		/** Colleagues off during the picked dates — excluding me and this very request. */
		overlaps() {
			if (!this.coverage) {
				return []
			}
			return this.coverage.events.filter((ev) => ev.employeeUid !== store.session.uid
				&& !(this.request && ev.requestId === this.request.id))
		},

		overlapCount() {
			return this.overlapNames.length
		},

		/** One entry per person: two requests from the same colleague are still one absence. */
		overlapNames() {
			return [...new Set(this.overlaps.map((ev) => ev.displayName))]
		},

		overlapLabel() {
			const names = this.overlapNames
			if (names.length <= 3) {
				return names.join(', ')
			}
			return t('absence', '{names} and {count} more', {
				names: names.slice(0, 3).join(', '),
				count: names.length - 3,
			})
		},

		/**
		 * Whether submitting would push the team to the admin's concurrency limit —
		 * the same arithmetic the manager sees when reviewing (CoverageService::
		 * getRequestCoverage), shown here so it is known before the ask, not after.
		 */
		coverageTight() {
			if (!this.coverage || !this.coverage.threshold) {
				return false
			}
			return this.coverage.maxConcurrent + 1 >= this.coverage.threshold
		},

		canSubmit() {
			if (!this.selectedType || !this.startIso || !this.endIso || this.workingDaysNum <= 0) {
				return false
			}
			if (this.hrMode && !this.selectedEmployee) {
				return false
			}
			if (this.replacementRequired && !this.selectedReplacement) {
				return false
			}
			if (this.requiresNote && this.reason.trim() === '') {
				return false
			}
			return true
		},
	},

	watch: {
		selectedType() {
			// Leaving "Sick leave" abandons any picked confidential category;
			// arriving on it starts from the explicit default, never an empty field.
			if (!this.showSickCategories) {
				this.sickCategory = null
			} else if (!this.sickCategory) {
				this.sickCategory = this.sickCategoryOptions[0]
			}
		},

		startIso() {
			this.recomputePrefill()
			this.scheduleCoverage()
		},

		endIso() {
			this.recomputePrefill()
			this.scheduleCoverage()
		},
	},

	beforeUnmount() {
		clearTimeout(this.coverageTimer)
	},

	async mounted() {
		await this.initFromProps()
		if (!this.hrMode && !store.balance.balances.length) {
			await store.loadMyBalance()
		}
		// The holidays load in the background; prefill refreshes once they are
		// there. Weekday counting works immediately without them.
		try {
			const year = new Date().getFullYear()
			const code = formatRegionCode(store.session.holidayCountry, store.session.holidayRegion)
			this.holidayChecker = makeHolidayChecker(await api.listApplyingHolidays(code, `${year - 1}-01-01`, `${year + 1}-12-31`))
			this.recomputePrefill()
		} catch {
			// Load failed: prefill stays weekday-only
		}
	},

	methods: {
		t,
		n,
		/** Debounced: the dates move a lot while a picker is being dragged. */
		scheduleCoverage() {
			clearTimeout(this.coverageTimer)
			this.coverageTimer = setTimeout(() => this.loadCoverage(), 350)
		},

		async loadCoverage() {
			if (!this.coverageApplies || !this.startIso || !this.endIso || this.endIso < this.startIso) {
				this.coverage = null
				return
			}
			const seq = ++this.coverageSeq
			try {
				const data = await api.getCoverage(this.startIso, this.endIso, 'team')
				if (seq === this.coverageSeq) {
					this.coverage = data
				}
			} catch {
				// Advisory only — a failed lookup must never stand between somebody and
				// their holiday, so it just leaves the hint out.
				if (seq === this.coverageSeq) {
					this.coverage = null
				}
			}
		},

		onWorkingDaysInput(v) {
			this.workingDays = v
			this.workingDaysTouched = true
		},

		/** Prefill the working-day count from the picked range, unless edited/editing. */
		recomputePrefill() {
			if (this.isEdit || this.workingDaysTouched || !this.startIso || !this.endIso) {
				return
			}
			const weekdays = parseWeekdays(store.session.workWeekdays || '1,2,3,4,5')
			this.workingDays = String(countWorkingDays(this.startIso, this.endIso, weekdays, this.holidayChecker))
		},

		formatDays(v) {
			if (v === null || v === undefined) {
				return '—'
			}
			return Number(v).toLocaleString(undefined, { maximumFractionDigits: 1 })
		},

		async initFromProps() {
			const types = this.typeOptions
			if (this.request) {
				const requestType = store.enabledLeaveTypes.find((x) => x.id === this.request.typeId) || null
				if (requestType && requestType.hrOnly && this.sickType) {
					// A confidential record edits as "Sick leave" + its category.
					this.selectedType = this.sickType
					this.sickCategory = { id: requestType.id, icon: requestType.icon, label: requestType.label }
				} else {
					this.selectedType = requestType || types[0]
				}
				this.disability = !!this.request.disability
				this.startIso = this.request.startDate
				this.endIso = this.request.endDate
				this.workingDays = String(this.request.workingDays)
				this.reason = this.request.reason || ''
				if (this.request.replacementUid) {
					this.selectedReplacement = { uid: this.request.replacementUid, displayName: this.request.replacementName || this.request.replacementUid }
				}
			} else {
				this.selectedType = types[0] || null
				const today = toIso(new Date())
				this.startIso = today
				this.endIso = today
				// Prefill the replacement used last time (self-service only).
				if (!this.hrMode) {
					this.selectedReplacement = this.pastReplacements()[0] || null
				}
			}
			// Offer colleagues used before so the dropdown isn't empty (self-service).
			if (!this.hrMode) {
				this.replacementOptions = this.pastReplacements()
				// Keep the current selection pickable even if it isn't in that list.
				if (this.selectedReplacement && !this.replacementOptions.some((o) => o.uid === this.selectedReplacement.uid)) {
					this.replacementOptions = [this.selectedReplacement, ...this.replacementOptions]
				}
			}
		},

		// Distinct colleagues used as replacement in the user's past requests, newest first.
		pastReplacements() {
			const seen = new Set()
			const list = []
			const own = store.requests
				.filter((r) => r.employeeUid === store.session.uid && r.replacementUid)
				.sort((a, b) => b.id - a.id)
			for (const r of own) {
				if (!seen.has(r.replacementUid)) {
					seen.add(r.replacementUid)
					list.push({ uid: r.replacementUid, displayName: r.replacementName || r.replacementUid })
				}
			}
			return list
		},

		async onEmployeeSearch(query) {
			if (!query || query.length < 2) {
				return
			}
			this.employeeLoading = true
			try {
				this.employeeOptions = await api.searchUsers(query)
			} catch {
				this.employeeOptions = []
			} finally {
				this.employeeLoading = false
			}
		},

		async onReplacementSearch(query) {
			if (!query || query.length < 2) {
				return
			}
			this.replacementLoading = true
			try {
				const users = await api.searchUsers(query)
				// A person can't be their own replacement.
				this.replacementOptions = users.filter((u) => u.uid !== this.subjectUid)
			} catch {
				this.replacementOptions = []
			} finally {
				this.replacementLoading = false
			}
		},

		async submit() {
			if (!this.canSubmit) {
				return
			}
			this.submitting = true
			const payload = {
				typeId: (this.showSickCategories && this.sickCategory && this.sickCategory.id !== null)
					? this.sickCategory.id
					: this.selectedType.id,

				startDate: this.startIso,
				endDate: this.endIso,
				workingDays: this.workingDaysNum,
				reason: this.reason,
			}
			if (this.hrMode && this.selectedEmployee) {
				payload.employeeUid = this.selectedEmployee.uid
			}
			if (this.showDisability) {
				payload.disability = this.disability
			}
			if (this.needsReplacement && this.selectedReplacement) {
				payload.replacementUid = this.selectedReplacement.uid
			}
			try {
				if (this.isEdit) {
					await store.updateRequest(this.request.id, payload)
				} else {
					await store.createRequest(payload)
				}
				this.$emit('saved')
			} catch (e) {
				showError(e.response?.data?.message || t('absence', 'Could not save the request'))
			} finally {
				this.submitting = false
			}
		},
	},
}
</script>

